const sentence = (zh, vi) => ({ zh, vi });

const section = (title, titleTranslation, sentences) => ({
  title,
  titleTranslation,
  sentences
});

const pair = (zh, vi) => ({ zh, vi });

const story = (level, id, title, titleTranslation, summary, topic, sections) => ({
  id,
  title,
  titleTranslation,
  summary,
  level,
  topic,
  estimatedMinutes: 20,
  sections
});

